import numpy as np,pandas as pd,pickle
from scipy.spatial.distance import cdist
from sklearn.model_selection import KFold
tr=pd.read_csv('/work/b3_htsteel_pareto_train.csv');po=pd.read_csv('/work/b3_htsteel_pareto_pool.csv');y=tr.iloc[:,-2:].values;s=y.std(axis=0)
# Chemistry metric deliberately de-emphasizes trace specification limits.
chem={'Cr':2,'Ni':3,'Mo':1,'Mn':2,'C':.1,'Ti':.5,'Si':1,'Nb':.5,'V':.5,'Al':.4,'Cu':1,'W':1}
def feats(df):
 c=np.array([df[k]/v for k,v in chem.items()]).T
 p=[]
 for pref in ['Heat treatment step 1','Heat treatment step 2','Heat treatment step 3','Secondary treatment step 1','Secondary treatment step 2','Secondary treatment step 3','Secondary treatment step 4','Aging']:
  t=df[pref+' temperature'].values.copy();d=df[pref+' duration'].values.copy();flag=t>30
  # Treat missing stage as a categorical absence, not a literal 0 C treatment.
  center=1000 if pref=='Heat treatment step 1' else 700
  p.extend([flag*2,(t-center)*flag/150,np.log1p(d)/3])
  if pref+' cooling' in df:p.append(np.log1p(df[pref+' cooling'].values)/3)
 return c,np.array(p).T
c,p=feats(tr);cq,pq=feats(po);dc=cdist(c,c);dp=cdist(p,p);dcq=cdist(cq,c);dpq=cdist(pq,p)
results=[]
for cw in [.25,.5,1,2,4]:
 for pw in [.5,1,2]:
  d=np.sqrt((dc*cw)**2+(dp*pw)**2);np.fill_diagonal(d,np.inf);dq=np.sqrt((dcq*cw)**2+(dpq*pw)**2)
  for k in [1,2,3,5,8,12]:
   for power in [1,2,4]:
    idx=np.argsort(d,axis=1)[:,:k];ds=np.take_along_axis(d,idx,axis=1);w=ds**(-power);w/=w.sum(axis=1)[:,None];loo=np.sum(w[:,:,None]*y[idx],axis=1)
    idxq=np.argsort(dq,axis=1)[:,:k];dsq=np.take_along_axis(dq,idxq,axis=1);wq=dsq**(-power);wq/=wq.sum(axis=1)[:,None];pred=np.sum(wq[:,:,None]*y[idxq],axis=1)
    rmse=np.sqrt(np.mean((loo-y)**2,axis=0));score=np.mean((rmse/s)**2)
    results.append((score,cw,pw,k,power,rmse,loo,pred))
results.sort(key=lambda r:r[0]);pickle.dump(results,open('/tmp/steel_nn.pkl','wb'))
for r in results[:12]:print(r[:6])
ids=[2,4,6,12,16,18,40,43,51,53,56,62,67,74,78,90,99]
for i in ids:print(po.candidate_id[i],np.mean([r[-1][i] for r in results[:10]],axis=0).round(1), [r[-1][i].round(1) for r in results[:3]])

